changeSet.sql:
            DROP TRIGGER IF EXISTS trg_before_insert_customer ON public.customer;


            CREATE OR REPLACE FUNCTION public.generate_customer_code(format_code text, current_value integer)
RETURNS text
LANGUAGE plpgsql
AS $$
DECLARE
            padding_length integer;
    padding_format text;
            BEGIN
    -- Trích xuất độ dài padding từ format_code
    padding_format := substring(format_code from '%(\d+)d');
    IF padding_format IS NOT NULL THEN
        padding_length := padding_format::integer;
            ELSE
        padding_length := 4; -- Mặc định nếu không có định dạng
            END IF;

    -- Thay thế ký tự đại diện `%d` hoặc `%0Nd` bằng giá trị hiện tại với padding phù hợp
            RETURN regexp_replace(format_code, '%\d*d', lpad(current_value::text, padding_length, '0'));
            END;
$$;


CREATE OR REPLACE FUNCTION public.before_insert_customer()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
            format_code text;
    current_valueE integer;
            BEGIN
    -- Lấy định dạng và current_value từ bảng `customer_code_formats` theo company và department
            SELECT format_customer_code, current_value INTO format_code, current_valueE
            FROM public.customer_code_formats
            WHERE company = NEW.company
              AND (department = NEW.department OR department IS NULL)
            ORDER BY department DESC
                LIMIT 1;

            -- Nếu không tìm thấy định dạng, xử lý lỗi
            IF format_code IS NULL THEN
        RAISE EXCEPTION 'No format found for company % and department %', NEW.company, NEW.department;
            END IF;

    -- Sinh mã khách hàng
    NEW.customer_code := public.generate_customer_code(format_code, current_valueE);
            RETURN NEW;
            END;
$$;


            CREATE TRIGGER trg_before_insert_customer
                BEFORE INSERT ON public.customer
                FOR EACH ROW
                EXECUTE FUNCTION public.before_insert_customer();


            SELECT public.generate_customer_code('KH-%05d', 123);
            SELECT public.generate_customer_code('KH-%04d', 123);
